ALTER TABLE public.trips ADD COLUMN IF NOT EXISTS min_temp TEXT;
ALTER TABLE public.trips ADD COLUMN IF NOT EXISTS max_temp TEXT;
ALTER TABLE public.trips ADD COLUMN IF NOT EXISTS weather TEXT;
ALTER TABLE public.trips ADD COLUMN IF NOT EXISTS start_point TEXT;
ALTER TABLE public.trips ADD COLUMN IF NOT EXISTS end_point TEXT;
ALTER TABLE public.trips ADD COLUMN IF NOT EXISTS package_type TEXT;
ALTER TABLE public.trips ADD COLUMN IF NOT EXISTS gst_percent NUMERIC DEFAULT 5.0;
ALTER TABLE public.trip_packages ADD COLUMN IF NOT EXISTS gst_percent NUMERIC DEFAULT 5.0;

-- 2. Ensure categories exist
INSERT INTO public.trip_categories (name, badge_label, icon_name, color_hex, is_special, display_order)
VALUES 
    ('Adventure', 'TREK', 'terrain', '#D32F2F', false, 1),
    ('Yatra', 'YATRA', 'temple_hindu', '#FF9800', false, 2),
    ('Package', 'VACATION', 'beach_access', '#00BCD4', true, 3),
    ('Road Trip', 'RIDE', 'motorcycle', '#4CAF50', true, 4)
ON CONFLICT (name) DO UPDATE SET 
    badge_label = EXCLUDED.badge_label,
    icon_name = EXCLUDED.icon_name,
    color_hex = EXCLUDED.color_hex,
    is_special = EXCLUDED.is_special,
    display_order = EXCLUDED.display_order;

-- 3. Truncate existing data to cleanly reload from Excel
TRUNCATE TABLE public.trip_packages, public.reviews, public.trips CASCADE;

