        '[{"day": 1, "title": "Rishikesh to Munsiyari", "description": "Day 01: Rishikesh to Munsiyari (7,200 ft) \u2013 Drive 320 km | 10\u201311 hrs. Journey through the scenic Kumaon Himalayas via Almora, Bageshwar, and Birthi Falls to reach Munsiyari, known for its spectacular views of the Panchachuli peaks. Overnight stay at a guest house.", "distance": "320 km", "time": "", "image": ""}, {"day": 2, "title": "Munsiyari", "description": "Day 02: Munsiyari (7,200 ft) to Lilam (6,100 ft) \u2013 Trek 12 km | 5\u20136 hrs. Begin the trek along the Gori Ganga River, passing through forests, waterfalls, and traditional Himalayan villages before reaching Lilam campsite.", "distance": "12 km", "time": "", "image": ""}, {"day": 3, "title": "Lilam", "description": "Day 03: Lilam (6,100 ft) to Bugdiar (8,950 ft) \u2013 Trek 14 km | 6\u20137 hrs. Trek through deep gorges, hanging bridges, and lush valleys while enjoying magnificent Himalayan scenery on the way to Bugdiar.", "distance": "14 km", "time": "", "image": ""}, {"day": 4, "title": "Bugdiar", "description": "Day 04: Bugdiar (8,950 ft) to Martoli (11,480 ft) \u2013 Trek 11 km | 5\u20136 hrs. Ascend gradually through the beautiful Johar Valley, passing ancient settlements and alpine landscapes before reaching the historic village of Martoli.", "distance": "11 km", "time": "", "image": ""}, {"day": 5, "title": "Martoli", "description": "Day 05: Martoli (11,480 ft) to Milam Village (11,810 ft) \u2013 Trek 11 km | 5\u20136 hrs. Continue trekking through remote Himalayan terrain to reach the abandoned heritage village of Milam, once an important stop on the Indo-Tibetan trade route", "distance": "11 km", "time": "", "image": ""}, {"day": 6, "title": "Milam Village", "description": "Day 06: Milam Village (11,810 ft) to Milam Glacier (12,950 ft) and back \u2013 Trek 12 km | 6\u20137 hrs. Explore the majestic Milam Glacier, one of the largest glaciers in the Kumaon Himalayas, and enjoy breathtaking views of surrounding snow-covered peaks before returning to Milam Village.", "distance": "12 km", "time": "", "image": ""}, {"day": 7, "title": "Milam Village", "description": "Day 07: Milam Village (11,810 ft) to Bugdiar (8,950 ft) \u2013 Trek 22 km | 8\u20139 hrs. Descend through scenic valleys and traditional Himalayan settlements back to Bugdiar for an overnight stay.", "distance": "22 km", "time": "", "image": ""}, {"day": 8, "title": "Bugdiar", "description": "Day 08: Bugdiar (8,950 ft) to Lilam (6,100 ft) \u2013 Trek 14 km | 5\u20136 hrs. Continue descending along the Gori Ganga Valley through forests and picturesque landscapes to reach Lilam.", "distance": "14 km", "time": "", "image": ""}, {"day": 9, "title": "Lilam", "description": "Day 09: Lilam (6,100 ft) to Munsiyari (7,200 ft) \u2013 Trek 12 km | 5\u20136 hrs. Complete the final stretch of the trek and return to Munsiyari for a comfortable overnight stay.", "distance": "12 km", "time": "", "image": ""}, {"day": 10, "title": "Munsiyari to Rishikesh", "description": "Day 10: Munsiyari to Rishikesh \u2013 Drive 320 km | 10\u201311 hrs. Drive back through the beautiful Kumaon Himalayas, concluding an unforgettable expedition to one of India''s largest glaciers.", "distance": "320 km", "time": "", "image": ""}]'::jsonb, '[{"location": "Airport: Pantnagar Airport", "price": 0}, {"location": "Railway: Kathgodam Railway Station", "price": 0}, {"location": "Base: Kathgodam", "price": 0}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
