    ) VALUES (
        'Panch Kedar Yatra', 'RUDRAPRYAG, Uttrakhand', '12D/11N', 'Difficult', '12070ft', 89000.0, 0, 5.0,
        'https://images.unsplash.com/photo-1506744038136-46273834b3fb', '["https://images.unsplash.com/photo-1506744038136-46273834b3fb"]'::jsonb,
        'Yatra', 'The Panch Kedar Yatra is one of the most breathtaking Himalayan journeys situated across the mesmerizing landscapes of RUDRAPRYAG, Uttrakhand. Rising to an impressive altitude of 12070ft over a duration of 12D/11N, this expedition offers a transcendent blend of ancient cultural lore, sacred alpine sanctuaries, and pristine high-altitude wilderness.

Traversing through dense oak, pine, and vibrant rhododendron canopies, travelers experience panoramic vistas of snow-crowned Himalayan peaks, sparkling glacial river valleys, and remote mountain hamlets steeped in centuries-old traditions. The journey commences from Haridwar, taking explorers deep into untamed valleys where cold, mountain weather graces the trails. Each step along this route reveals untouched flora, alpine meadows, and timeless folklore cherished by the local indigenous communities.

Whether ascending dramatic ridge lines, camping beneath star-studded Himalayan skies, or immersing in the spiritual resonance of the high Himalayas, the Panch Kedar Yatra stands as an unforgettable expedition of exploration, resilience, and natural majesty.', 'The Panch Kedar Yatra is one of the most breathtaking Himalayan journeys situated across the mesmerizing landscapes of RUDRAPRYAG, Uttrakhand. Rising to an impressive altitude of 12070ft over a duration of 12D/11N, this expedition offers a transcendent blend of ancient cultural lore, sacred alpine sanctuaries, and pristine high-altitude wilderness.

Traversing through dense oak, pine, and vibrant rhododendron canopies, travelers experience panoramic vistas of snow-crowned Himalayan peaks, sparkling glacial river valleys, and remote mountain hamlets steeped in centuries-old traditions. The journey commences from Haridwar, taking explorers deep into untamed valleys where cold, mountain weather graces the trails. Each step along this route reveals untouched flora, alpine meadows, and timeless folklore cherished by the local indigenous communities.

Whether ascending dramatic ridge lines, camping beneath star-studded Himalayan skies, or immersing in the spiritual resonance of the high Himalayas, the Panch Kedar Yatra stands as an unforgettable expedition of exploration, resilience, and natural majesty.',
        '[{"day": 1, "title": "Rishikesh to Guptkashi", "description": "Day 1: Rishikesh to Guptkashi (4,300 ft) \u2013 Drive approximately 210 km in 8\u20139 hours via Devprayag, Srinagar and Rudraprayag to reach Guptkashi. Enjoy scenic views of the Alaknanda and Mandakini valleys before checking into the hotel for dinner and an overnight stay. Meals: Dinner | Stay: Guptkashi.", "distance": "210 km", "time": "", "image": ""}, {"day": 2, "title": "Guptkashi", "description": "Day 2: Guptkashi \u2013 Gaurikund \u2013 Kedarnath (11,755 ft) \u2013 After breakfast, drive to Gaurikund and begin the 16 km trek to the sacred Kedarnath Temple, taking around 7\u20139 hours. Reach Kedarnath by evening, attend the aarti and spend the night near the temple. Meals: Breakfast & Dinner | Stay: Kedarnath.", "distance": "16 km", "time": "", "image": ""}, {"day": 3, "title": "Kedarnath", "description": "Day 3: Kedarnath \u2013 Gaurikund \u2013 Guptkashi (4,300 ft) \u2013 Attend the morning darshan at Kedarnath Temple before trekking back to Gaurikund and driving to Guptkashi. Relax at the hotel after completing the pilgrimage to the first Kedar. Meals: Breakfast & Dinner | Stay: Guptkashi.", "distance": "", "time": "", "image": ""}, {"day": 4, "title": "Guptkashi", "description": "Day 4: Guptkashi \u2013 Ransi \u2013 Madmaheshwar (10,830 ft) \u2013 Drive to Ransi village and trek approximately 16 km through forests, villages and meadows to reach the sacred Madmaheshwar Temple. Enjoy magnificent Himalayan views before an overnight stay near the temple. Meals: Breakfast & Dinner | Stay: Madmaheshwar.", "distance": "16 km", "time": "", "image": ""}, {"day": 5, "title": "Madmaheshwar", "description": "Day 5: Madmaheshwar \u2013 Budha Madmaheshwar \u2013 Ransi (11,500 ft) \u2013 Visit Budha Madmaheshwar in the morning for spectacular sunrise views of Chaukhamba peaks and then descend back to Ransi village for dinner and overnight stay. Meals: Breakfast & Dinner | Stay: Ransi.", "distance": "", "time": "", "image": ""}, {"day": 6, "title": "Ransi to Chopta", "description": "Day 6: Ransi to Chopta (8,790 ft) \u2013 Drive approximately 85 km in 4\u20135 hours via Ukhimath to reach Chopta, popularly known as the ''Mini Switzerland of Uttarakhand''. Relax amidst lush meadows and forests. Meals: Breakfast & Dinner | Stay: Chopta.", "distance": "85 km", "time": "", "image": ""}, {"day": 7, "title": "Chopta", "description": "Day 7: Chopta \u2013 Tungnath \u2013 Chandrashila \u2013 Chopta (12,100 ft) \u2013 Trek around 5 km to the world''s highest Shiva temple at Tungnath and continue to Chandrashila Peak for panoramic Himalayan views. Return to Chopta for an overnight stay. Meals: Breakfast & Dinner | Stay: Chopta.", "distance": "5 km", "time": "", "image": ""}, {"day": 8, "title": "Chopta to Sagar Village", "description": "Day 8: Chopta to Sagar Village (6,600 ft) \u2013 Drive approximately 70 km in 3\u20134 hours to Sagar Village, the base point for Rudranath Trek. Spend the evening preparing for the next pilgrimage section. Meals: Breakfast & Dinner | Stay: Sagar Village.", "distance": "70 km", "time": "", "image": ""}, {"day": 9, "title": "Sagar Village to Rudranath", "description": "Day 9: Sagar Village to Rudranath (11,800 ft) \u2013 Trek nearly 20 km in 8\u20139 hours through dense forests, alpine meadows and mountain ridges to reach the sacred Rudranath Temple, nestled amidst stunning Himalayan landscapes. Meals: Breakfast & Dinner | Stay: Rudranath.", "distance": "20 km", "time": "", "image": ""}, {"day": 10, "title": "Rudranath to Sagar Village", "description": "Day 10: Rudranath to Sagar Village (6,600 ft) \u2013 Descend back through beautiful meadows and forests to Sagar Village, completing the pilgrimage to the fourth Kedar. Meals: Breakfast & Dinner | Stay: Sagar Village.", "distance": "", "time": "", "image": ""}, {"day": 11, "title": "Sagar Village", "description": "Day 11: Sagar Village \u2013 Helang \u2013 Kalpeshwar \u2013 Joshimath (6,150 ft) \u2013 Drive to Helang and trek approximately 2 km to visit Kalpeshwar Temple, the fifth and final Kedar, located in the serene Urgam Valley. Later continue to Joshimath for an overnight stay. Meals: Breakfast & Dinner | Stay: Joshimath.", "distance": "2 km", "time": "", "image": ""}, {"day": 12, "title": "Joshimath to Rishikesh", "description": "Day 12: Joshimath to Rishikesh \u2013 After breakfast, drive approximately 255 km in 8\u20139 hours via Karnaprayag, Rudraprayag and Devprayag to reach Rishikesh, concluding the spiritually fulfilling Panch Kedar Yatra with divine blessings and unforgettable Himalayan memories.", "distance": "255 km", "time": "", "image": ""}]'::jsonb, '[{"location": "Airport: Jolly Grant Airport", "price": 0}, {"location": "Railway: Rishikesh Railway Station", "price": 0}, {"location": "Base: Haridwar", "price": 0}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
        30.7333, 76.7794, '12070ft', '', '',
        '{"Ideal Season": "May\u2013Jun, Sep\u2013Oct | Temp: -3\u2103'' to 18\u2103'' | Weather: Cold, mountain weather"}'::jsonb, 'May–Jun, Sep–Oct', '679 km', 'Haridwar', 'Haridwar',
        'Jolly Grant Airport', 'Rishikesh Railway Station', 'yes', '4300ft', '12070ft',
        '-3℃''', '18℃''', 'Cold, mountain weather', 'Uttrakhand', 'RUDRAPRYAG',
        'YATRA', 5.0
    ) RETURNING id INTO tid;
