        '[{"day": 1, "title": "Kasol to Barshaini", "description": "Day 1: Kasol to Barshaini \u2013 Trek to Kheerganga (9,700 ft) \u2013 Drive 16 km to Barshaini and trek 12 km in 5\u20136 hours through forests, waterfalls and scenic mountain trails. Reach Kheerganga and relax amidst its famous hot springs.", "distance": "12 km", "time": "", "image": ""}, {"day": 2, "title": "Kheerganga to Tunda Bhuj", "description": "Day 2: Kheerganga to Tunda Bhuj (10,500 ft) \u2013 Trek 14 km in 6\u20137 hours along the Parvati River through dense forests and rocky terrain. Camp at Tunda Bhuj surrounded by towering cliffs and alpine scenery.", "distance": "14 km", "time": "", "image": ""}, {"day": 3, "title": "Tunda Bhuj to Thakur Kuan", "description": "Day 3: Tunda Bhuj to Thakur Kuan (11,800 ft) \u2013 Cover 12 km in 5\u20136 hours across meadows, glacial streams and moraine sections. Enjoy magnificent views of the upper Parvati Valley before reaching camp.", "distance": "12 km", "time": "", "image": ""}, {"day": 4, "title": "Thakur Kuan to Odi Thach", "description": "Day 4: Thakur Kuan to Odi Thach (12,800 ft) \u2013 Trek 11 km in 5\u20136 hours through rugged landscapes and alpine terrain. Reach Odi Thach campsite amidst spectacular Himalayan surroundings.", "distance": "11 km", "time": "", "image": ""}, {"day": 5, "title": "Odi Thach to Mantalai Lake", "description": "Day 5: Odi Thach to Mantalai Lake (13,900 ft) \u2013 Trek 10 km in 5\u20136 hours over glacial moraine and boulder fields to the sacred Mantalai Lake. Camp beside the pristine lake surrounded by snow-covered peaks.", "distance": "10 km", "time": "", "image": ""}, {"day": 6, "title": "Acclimatization at Mantalai Lake", "description": "Day 6: Acclimatization at Mantalai Lake (13,900 ft) \u2013 Spend the day acclimatizing and exploring the high-altitude surroundings. Short hikes around the campsite prepare trekkers for the challenging pass crossing ahead.", "distance": "", "time": "", "image": ""}, {"day": 7, "title": "Mantalai Lake to Pin Parvati Base Camp", "description": "Day 7: Mantalai Lake to Pin Parvati Base Camp (15,100 ft) \u2013 Trek 8 km in 5\u20136 hours through glaciers and snowfields towards the base camp. Enjoy breathtaking views of the surrounding Himalayan ranges.", "distance": "8 km", "time": "", "image": ""}, {"day": 8, "title": "Base Camp", "description": "Day 8: Base Camp \u2013 Pin Parvati Pass \u2013 Wichkurung Thach (14,400 ft) \u2013 Trek 14 km in 10\u201312 hours crossing Pin Parvati Pass (17,450 ft). Traverse glaciers, steep snow slopes and descend into the stark landscapes of Spiti Valley.", "distance": "14 km", "time": "", "image": ""}, {"day": 9, "title": "Wichkurung Thach to Mudh Village", "description": "Day 9: Wichkurung Thach to Mudh Village (12,500 ft) \u2013 Trek 16 km in 6\u20137 hours through the Pin Valley''s barren terrain and beautiful valleys. Reach Mudh Village and experience the unique culture of Spiti.", "distance": "16 km", "time": "", "image": ""}, {"day": 10, "title": "Mudh Village to Kaza", "description": "Day 10: Mudh Village to Kaza (12,500 ft) \u2013 Drive 50 km in 2\u20133 hours through the scenic Pin Valley to Kaza. Explore the vibrant town and enjoy a comfortable overnight stay.", "distance": "50 km", "time": "", "image": ""}, {"day": 11, "title": "Kaza to Manali", "description": "Day 11: Kaza to Manali (6,730 ft) \u2013 Drive approximately 200 km in 8\u20139 hours via Kunzum Pass and Atal Tunnel to reach Manali, concluding one of the Himalayas'' most adventurous expeditions.", "distance": "200 km", "time": "", "image": ""}]'::jsonb, '[{"location": "Airport: Bhuntar Airport kullu manali", "price": 0}, {"location": "Railway: Chandigarh Railway Station", "price": 0}, {"location": "Base: Kullu", "price": 0}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
