        '[{"day": 1, "title": "Arrival in Manali", "description": "Day 1: Arrival in Manali (6,730 ft) \u2013 Arrive in Manali, complete bike allotment and briefing session. Spend the day exploring Mall Road, Hadimba Temple and preparing for the ultimate Himalayan ride.", "distance": "", "time": "", "image": ""}, {"day": 2, "title": "Manali to Sarchu", "description": "Day 2: Manali to Sarchu (14,070 ft) \u2013 Ride approximately 220 km in 8\u20139 hours via Atal Tunnel (10,171 ft), Jispa, Deepak Tal, Suraj Tal and Baralacha La Pass (16,040 ft). Reach Sarchu after crossing some of the most scenic sections of the Manali\u2013Leh Highway.", "distance": "220 km", "time": "", "image": ""}, {"day": 3, "title": "Sarchu to Leh", "description": "Day 3: Sarchu to Leh (11,500 ft) \u2013 Ride 250 km in 8\u20139 hours crossing the famous Gata Loops, Nakee La Pass (15,547 ft), Lachulung La Pass (16,616 ft), Pang, More Plains and Tanglang La Pass (17,480 ft) before arriving in Leh.", "distance": "250 km", "time": "", "image": ""}, {"day": 4, "title": "Leh to Nubra Valley via Khardung La Pass", "description": "Day 4: Leh to Nubra Valley via Khardung La Pass (18,380 ft) \u2013 Ride 125 km in 5\u20136 hours crossing the legendary Khardung La Pass, one of the world''s highest motorable roads. Explore Diskit Monastery, Hunder Sand Dunes and Double-Humped Camel Safari.", "distance": "125 km", "time": "", "image": ""}, {"day": 5, "title": "Nubra Valley to Turtuk and Back", "description": "Day 5: Nubra Valley to Turtuk and Back (9,800 ft) \u2013 Ride around 170 km along the Shyok River to visit Turtuk Village, India''s last village near the border. Experience Balti culture, apricot orchards and traditional Himalayan life before returning to Nubra.", "distance": "170 km", "time": "", "image": ""}, {"day": 6, "title": "Nubra Valley to Pangong Lake", "description": "Day 6: Nubra Valley to Pangong Lake (14,270 ft) \u2013 Ride 160 km through the breathtaking Shyok Valley, passing Durbuk and Tangtse. Reach Pangong Lake and enjoy mesmerizing sunset views beside the famous high-altitude lake.", "distance": "160 km", "time": "", "image": ""}, {"day": 7, "title": "Pangong Lake to Leh via Chang La Pass", "description": "Day 7: Pangong Lake to Leh via Chang La Pass (17,590 ft) \u2013 Ride back to Leh crossing Chang La Pass, one of Ladakh''s highest mountain passes. En route visit Thiksey Monastery, Shey Palace and Druk White Lotus School (3 Idiots School).", "distance": "", "time": "", "image": ""}, {"day": 8, "title": "Leh to Kargil", "description": "Day 8: Leh to Kargil (8,780 ft) \u2013 Ride 215 km through the historic Sham Valley visiting Alchi Monastery, Basgo Palace, Magnetic Hill, Lamayuru Monastery and Fotu La Pass (13,478 ft). Reach Kargil for an overnight stay.", "distance": "215 km", "time": "", "image": ""}, {"day": 9, "title": "Kargil to Srinagar", "description": "Day 9: Kargil to Srinagar (5,200 ft) \u2013 Ride 205 km via Namika La Pass (12,198 ft), Drass, Kargil War Memorial and Zojila Pass (11,575 ft) before descending into the beautiful Kashmir Valley and reaching Srinagar.", "distance": "205 km", "time": "", "image": ""}, {"day": 10, "title": "Departure from Srinagar", "description": "Day 10: Departure from Srinagar \u2013 After breakfast, check out and depart with unforgettable memories of conquering iconic Himalayan passes and riding across two of India''s most spectacular mountain regions.", "distance": "", "time": "", "image": ""}]'::jsonb, '[{"location": "Airport: Kullu\u2013Manali Airport (Bhuntar)", "price": 0}, {"location": "Railway: Joginder Nagar Railway Station", "price": 0}, {"location": "Base: Manali", "price": 0}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
