        '[{"day": 1, "title": "Arrival in Leh", "description": "Day 1: Arrival in Leh (11,500 ft) \u2013 Arrive in Leh and spend the day acclimatizing to the high altitude. Explore Leh Market, Shanti Stupa and nearby monasteries while preparing for the trek.", "distance": "", "time": "", "image": ""}, {"day": 2, "title": "Leh to Skiu", "description": "Day 2: Leh to Skiu (11,150 ft) \u2013 Drive 70 km to Chilling and begin the trek to Skiu, covering 8 km in 3\u20134 hours. Walk along the Markha River through barren landscapes and traditional Ladakhi villages.", "distance": "8 km", "time": "", "image": ""}, {"day": 3, "title": "Skiu to Markha", "description": "Day 3: Skiu to Markha (12,270 ft) \u2013 Trek 20 km in 7\u20138 hours through scenic valleys, willow groves and small settlements. Reach Markha village, the largest settlement in the valley, surrounded by spectacular mountain scenery.", "distance": "20 km", "time": "", "image": ""}, {"day": 4, "title": "Markha to Hankar", "description": "Day 4: Markha to Hankar (13,780 ft) \u2013 Trek 13 km in 5\u20136 hours following the Markha River while enjoying magnificent views of Kang Yatse Peak. Arrive at Hankar campsite for an overnight stay.", "distance": "13 km", "time": "", "image": ""}, {"day": 5, "title": "Hankar to Nimaling", "description": "Day 5: Hankar to Nimaling (15,750 ft) \u2013 Trek 10 km in 4\u20135 hours through vast alpine meadows and rugged mountain terrain. Reach Nimaling, one of the most beautiful high-altitude campsites in Ladakh.", "distance": "10 km", "time": "", "image": ""}, {"day": 6, "title": "Nimaling to Chokdo via Kongmaru La Pass", "description": "Day 6: Nimaling to Chokdo via Kongmaru La Pass (17,060 ft) \u2013 Trek 15 km in 7\u20138 hours crossing Kongmaru La Pass, the highest point of the trek. Descend through dramatic gorges and colourful canyon landscapes to reach Chokdo.", "distance": "15 km", "time": "", "image": ""}, {"day": 7, "title": "Chokdo to Leh", "description": "Day 7: Chokdo