    INSERT INTO public.trips (
        title, location, duration, difficulty, altitude, base_price, discount_percent, rating,
        image_url, images, category, description, trip_story, itinerary, pickup_options, inclusions,
        exclusions, carry_list, latitude, longitude, peak_elevation, trail_type, orientation,
        seasonal_info, best_months, total_distance, start_point, end_point, airport, railway,
        buses_cabs, min_height, max_height, min_temp, max_temp, weather, state, district,
        package_type, gst_percent
    ) VALUES (
        'Goechala Trek', 'West Sikkim, Sikkim', '11D/10N', 'Moderate', '16100 ft', 26000.0, 0, 5.0,
        'https://images.unsplash.com/photo-1506744038136-46273834b3fb', '["https://images.unsplash.com/photo-1506744038136-46273834b3fb"]'::jsonb,
        'Adventure', 'The Goechala Trek is one of the most breathtaking Himalayan journeys situated across the mesmerizing landscapes of West Sikkim, Sikkim. Rising to an impressive altitude of 16100 ft over a duration of 11D/10N, this expedition offers a transcendent blend of ancient cultural lore, sacred alpine sanctuaries, and pristine high-altitude wilderness.

Traversing through dense oak, pine, and vibrant rhododendron canopies, travelers experience panoramic vistas of snow-crowned Himalayan peaks, sparkling glacial river valleys, and remote mountain hamlets steeped in centuries-old traditions. The journey commences from Yuksom, taking explorers deep into untamed valleys where pleasant days, freezing nights and changing mountain weather. graces the trails. Each step along this route reveals untouched flora, alpine meadows, and timeless folklore cherished by the local indigenous communities.

Whether ascending dramatic ridge lines, camping beneath star-studded Himalayan skies, or immersing in the spiritual resonance of the high Himalayas, the Goechala Trek stands as an unforgettable expedition of exploration, resilience, and natural majesty.', 'The Goechala Trek is one of the most breathtaking Himalayan journeys situated across the mesmerizing landscapes of West Sikkim, Sikkim. Rising to an impressive altitude of 16100 ft over a duration of 11D/10N, this expedition offers a transcendent blend of ancient cultural lore, sacred alpine sanctuaries, and pristine high-altitude wilderness.

Traversing through dense oak, pine, and vibrant rhododendron canopies, travelers experience panoramic vistas of snow-crowned Himalayan peaks, sparkling glacial river valleys, and remote mountain hamlets steeped in centuries-old traditions. The journey commences from Yuksom, taking explorers deep into untamed valleys where pleasant days, freezing nights and changing mountain weather. graces the trails. Each step along this route reveals untouched flora, alpine meadows, and timeless folklore cherished by the local indigenous communities.

Whether ascending dramatic ridge lines, camping beneath star-studded Himalayan skies, or immersing in the spiritual resonance of the high Himalayas, the Goechala Trek stands as an unforgettable expedition of exploration, resilience, and natural majesty.',
        '[{"day": 1, "title": "NJP/Bagdogra to Yuksom", "description": "Day 1: NJP/Bagdogra to Yuksom (5,840 ft) \u2013 Drive approximately 150 km in 7\u20138 hours from NJP Railway Station or Bagdogra Airport to Yuksom, the historic gateway to the trek. The scenic route passes through lush valleys, rivers, tea gardens, and mountain roads before reaching Yuksom. Spend the evening exploring the village and preparing for the trek. Overnight stay in a guesthouse.", "distance": "150 km", "time": "", "image": ""}, {"day": 2, "title": "Yuksom to Sachen", "description": "Day 2: Yuksom to Sachen (7,200 ft) \u2013 Trek 8 km in about 5\u20136 hours through dense forests of oak, pine, and magnolia. The trail gradually ascends alongside the Prek Chu River, crossing several suspension bridges and passing through beautiful woodland sections before reaching the peaceful campsite at Sachen. Overnight stay in tents.", "distance": "8 km", "time": "", "image": ""}, {"day": 3, "title": "Sachen to Tshoka", "description": "Day 3: Sachen to Tshoka (9,700 ft) \u2013 Cover around 8 km in 5\u20136 hours as the trail climbs steadily through Bakhim and dense rhododendron forests. Enjoy occasional views of snow-capped peaks while traversing steep sections before arriving at the charming Tibetan settlement of Tshoka, surrounded by forests and mountains. Overnight stay in tents.", "distance": "8 km", "time": "", "image": ""}, {"day": 4, "title": "Tshoka to Dzongri", "description": "Day 4: Tshoka to Dzongri (13,200 ft) \u2013 Trek nearly 9 km in 6\u20137 hours through rhododendron forests, alpine meadows, and the Deorali region. As altitude increases, magnificent views of Kanchenjunga, Pandim, Kabru, and Rathong begin to unfold. Reach Dzongri by evening and camp amidst spectacular Himalayan scenery.", "distance": "9 km", "time": "", "image": ""}, {"day": 5, "title": "Acclimatization at Dzongri", "description": "Day 5: Acclimatization at Dzongri (13,200 ft) \u2013 Spend the day acclimatizing to the higher altitude with a short hike of about 2 km to Dzongri Top (13,800 ft). Witness a breathtaking sunrise over Kanchenjunga and neighboring peaks before returning to camp. The remainder of the day is reserved for rest, acclimatization, and exploration around Dzongri. Overnight stay in tents.", "distance": "2 km", "time": "", "image": ""}, {"day": 6, "title": "Dzongri to Thansing", "description": "Day 6: Dzongri to Thansing (12,900 ft) \u2013 Trek approximately 10 km in 5\u20136 hours across open alpine meadows and ridgelines. Descend gradually towards Kokchurung and continue along the Prek Chu River before reaching the expansive campsite at Thansing, which offers stunning views of Mt. Pandim towering overhead. Overnight camping.", "distance": "10 km", "time": "", "image": ""}, {"day": 7, "title": "Thansing to Lamuney", "description": "Day 7: Thansing to Lamuney (13,600 ft) \u2013 Cover nearly 4 km in 2\u20133 hours on a gradual ascent through glacial valleys and high-altitude grasslands. This shorter trekking day helps with acclimatization and provides ample time to relax and enjoy the magnificent mountain surroundings at Lamuney. Overnight stay in tents.", "distance": "4 km", "time": "", "image": ""}, {"day": 8, "title": "Lamuney to Goechala View Point", "description": "Day 8: Lamuney to Goechala View Point (15,100 ft) and Kokchurung \u2013 Begin before dawn and trek around 15\u201318 km in 10\u201312 hours. Pass the pristine Samiti Lake before climbing to Goechala View Point, which offers unparalleled views of Kanchenjunga and the surrounding Himalayan peaks. After spending time at the viewpoint, descend through Thansing and continue to Kokchurung for an overnight stay in tents.", "distance": "15\u201318 km", "time": "", "image": ""}, {"day": 9, "title": "Kokchurung to Tshoka", "description": "Day 9: Kokchurung to Tshoka (9,700 ft) \u2013 Descend approximately 16 km in 6\u20137 hours through rhododendron forests, wooden bridges, and scenic mountain trails. The route provides excellent opportunities to appreciate the region''s rich flora and birdlife before reaching the familiar campsite at Tshoka. Overnight stay in tents.", "distance": "16 km", "time": "", "image": ""}, {"day": 10, "title": "Tshoka to Yuksom", "description": "Day 10: Tshoka to Yuksom (5,840 ft) \u2013 Trek about 16 km in 6\u20137 hours, retracing the trail through Bakhim and Sachen. Cross suspension bridges and dense forests before finally reaching Yuksom, marking the completion of the trekking journey. Overnight stay in a hotel or guesthouse.", "distance": "16 km", "time": "", "image": ""}, {"day": 11, "title": "Yuksom to NJP/Bagdogra", "description": "Day 11: Yuksom to NJP/Bagdogra \u2013 Drive approximately 150 km in 7\u20138 hours back to NJP Railway Station or Bagdogra Airport. Enjoy the final views of Sikkim''s valleys, rivers, and mountain landscapes as the memorable Goechala Trek comes to an end.", "distance": "150 km", "time": "", "image": ""}]'::jsonb, '[{"location": "Airport: Bagdogra Airport", "price": 0}, {"location": "Railway: New Jalpaiguri Railway Station", "price": 0}, {"location": "Base: Yuksom", "price": 0}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb,
        30.7333, 76.7794, '16100 ft', '', '',
